import base64
import pathlib
import re
import socket
import struct
import subprocess
import sys
import time

# A real RTSP/RTP playback source with H.264 generated by FFmpeg.
def serve(conn, uri, nals):
    sps = next(n for n in nals if n[0] & 31 == 7)
    pps = next(n for n in nals if n[0] & 31 == 8)
    buf = b""
    while True:
        while b"\r\n\r\n" not in buf:
            data = conn.recv(65536)
            if not data:
                return
            buf += data
        request, buf = buf.split(b"\r\n\r\n", 1)
        request = request.decode()
        method = request.split(" ", 1)[0]
        seq = re.search(r"CSeq: (\d+)", request, re.I).group(1)
        body = b""
        headers = ""
        if method == "OPTIONS":
            headers = "Public: OPTIONS, DESCRIBE, SETUP, PLAY, TEARDOWN\r\n"
        elif method == "DESCRIBE":
            parameters = base64.b64encode(sps).decode() + "," + base64.b64encode(pps).decode()
            body = ("v=0\r\no=- 0 0 IN IP4 127.0.0.1\r\ns=fixture\r\nc=IN IP4 127.0.0.1\r\n"
                    "t=0 0\r\na=control:*\r\nm=video 0 RTP/AVP 96\r\na=rtpmap:96 H264/90000\r\n"
                    "a=fmtp:96 packetization-mode=1;sprop-parameter-sets=" + parameters +
                    "\r\na=control:trackID=0\r\n").encode()
            headers = f"Content-Type: application/sdp\r\nContent-Base: {uri}/\r\nContent-Length: {len(body)}\r\n"
        elif method == "SETUP":
            headers = "Session: 12345678\r\nTransport: RTP/AVP/TCP;unicast;interleaved=0-1\r\n"
        elif method == "PLAY":
            headers = f"Session: 12345678\r\nRTP-Info: url={uri}/trackID=0;seq=1;rtptime=0\r\n"
        conn.sendall(f"RTSP/1.0 200 OK\r\nCSeq: {seq}\r\n{headers}\r\n".encode() + body)
        if method == "PLAY":
            stream(conn, nals)
            return


def stream(conn, nals):
    sequence = 1
    timestamp = -9000

    def packet(payload, marker):
        nonlocal sequence
        data = struct.pack("!BBHII", 0x80, 96 | (0x80 if marker else 0),
                           sequence & 65535, timestamp & 0xffffffff, 0x10203040) + payload
        conn.sendall(b"$\x00" + struct.pack("!H", len(data)) + data)
        sequence += 1

    for _ in range(60):
        for nal in nals:
            kind = nal[0] & 31
            if kind == 9:
                timestamp += 9000
                time.sleep(0.1)
                continue
            if len(nal) < 1300:
                packet(nal, kind in (1, 5))
            else:
                for offset in range(1, len(nal), 1200):
                    chunk = nal[offset:offset + 1200]
                    end = offset + len(chunk) == len(nal)
                    header = bytes([(nal[0] & 0xe0) | 28,
                                    kind | (0x80 if offset == 1 else 0) | (0x40 if end else 0)])
                    packet(header + chunk, end and kind in (1, 5))


if __name__ == "__main__":
    ffmpeg, ready = sys.argv[1:3]
    video = subprocess.check_output([ffmpeg, "-hide_banner", "-loglevel", "error", "-f", "lavfi",
                                     "-i", "testsrc=size=160x120:rate=10", "-t", "4", "-c:v", "libx264",
                                     "-pix_fmt", "yuv420p", "-preset", "ultrafast", "-tune", "zerolatency",
                                     "-x264-params", "keyint=10:min-keyint=10:scenecut=0:aud=1:repeat-headers=1",
                                     "-f", "h264", "pipe:1"])
    nals = [n for n in re.split(b"\x00\x00\x00\x01|\x00\x00\x01", video) if n]
    with socket.socket() as listener:
        listener.bind(("127.0.0.1", 0))
        listener.listen()
        uri = f"rtsp://127.0.0.1:{listener.getsockname()[1]}/stream"
        pathlib.Path(ready).write_text(uri, encoding="utf-8")
        while True:
            conn, _ = listener.accept()
            with conn:
                conn.settimeout(35)
                try:
                    serve(conn, uri, nals)
                except (ConnectionResetError, BrokenPipeError):
                    print("RTSP client disconnected", flush=True)
